head.script:
scwin.onpageload = function() {
	scwin.code = [
		{ "appCd": "CNG", "comCdDesc": "CNG", "rowStatus": "R" },
		{ "appCd": "DND", "comCdDesc": "DND", "rowStatus": "R" },
		{ "appCd": "DRO", "comCdDesc": "DRO", "rowStatus": "R" },
		{ "appCd": "FLT", "comCdDesc": "LSE", "rowStatus": "R" },
		{ "appCd": "TPR", "comCdDesc": "TPR", "rowStatus": "R" },
		{ "appCd": "FES", "comCdDesc": "FES", "rowStatus": "R" },
		{ "appCd": "TRS", "comCdDesc": "TRS", "rowStatus": "R" },
		{ "appCd": "JOS", "comCdDesc": "CNG", "rowStatus": "R" },
		{ "appCd": "LSE", "comCdDesc": "LSE", "rowStatus": "R" },
		{ "appCd": "PSO", "comCdDesc": "MNR", "rowStatus": "R" },
		{ "appCd": "FAR", "comCdDesc": "FINANCE ACCOUNT RECEIVABLE", "rowStatus": "R" },
		{ "appCd": "FAP", "comCdDesc": "FINANCE ACCOUNT PAYABLE", "rowStatus": "R" }
	];
	dlCode.setJSON(scwin.code);
	dlList.setJSON([{
		"appCd": "DND"
	}]);
};
scwin.rowAdd_onclick = function() {
	dlList.insertRow(0);
	grdList.setCellReadOnly(0, "appCd", false);
	grdList.setCellReadOnly(0, "appCd2", false);
	var info = {
		inputType: "autoComplete",
		options: {
			"caseSensitive": "false",
			viewType: "icon",
			selectedData: "false",
			chooseOption: "true",
			chooseOptionLabel: "$blank"
		},
		itemSet: {
			nodeset: "data:dlCode",
			label: "comCdDesc",
			value: "appCd"
		}
	};
	grdList.setCellInputType(0, "appCd2", info);
	grdList.setFocusedCell(0, "appCd", true);
};
